### Describe the bug

`p.array` breaks when value contains comma:

```ts
const foo2 = testRepository.create({ names: ['hello,world', 'hello'] })
```
when select, foo2 became `names: ["hello", "world", "hello"]`


### Reproduction

## create table
```sql
CREATE TABLE test (
   id INTEGER PRIMARY KEY AUTOINCREMENT,
   names TEXT
);
```

## code
```ts
#!/usr/bin/env tsx

import { defineEntity, p } from '@mikro-orm/core'
import { MikroORM } from '@mikro-orm/sqlite'

const Test = defineEntity({
  name: 'test',
  properties: {
    id: p.integer().primary().autoincrement(),
    names: p.array<string>().nullable(),
  },
})

;(async () => {
  const orm = await MikroORM.init({
    entities: [Test],
    debug: true,
    dbName: __dirname + '/test.db',
  })
  const em = orm.em.fork()
  const testRepository = em.getRepository(Test)
  console.log(await testRepository.findAll())

  // const foo1 = testRepository.create({ names: ['hello', 'world'] })
  // em.persist(foo1)
  // const foo2 = testRepository.create({ names: ['hello,world', 'hello'] })
  // em.persist(foo2)
  // await em.flush()
})()
```

## select result

[query] select `t0`.* from `test` as `t0` [took 0 ms, 3 results]
[
  test { id: 1, names: [ 'hello', 'world' ] },
  test { id: 2, names: [ 'hello', 'world' ] },
  test { id: 3, names: [ 'hello', 'world', 'hello' ] }
]

## Advise

align storage behavior to `p.json<string[]>()` to avoid this.


